/**
 * 负责盗贼原状态读取、玩家知识副本和初始选择工具解析。输入为原角色记录、World准备状态或未知工具对象；
 * 输出合法原槽引用、policy／remaining／choice新副本或原明确拒绝，不发牌、不替换身份或授予选择许可。
 * 三字段形状、原政策与0／1资源保持；字段契约由共享data-ports拥有，不强化descriptor或Proxy接受面。
 * 展示只在setup pending时保留存储remaining，其它状态归0；这不会消费或更新live库存。
 */
import type { ThiefState, ThiefReadState } from "@ai-werewolf-arena/game-contract";
import { Role, type RoleComponent, type World } from "../../../../core/domain";
import { thiefSetupStatus } from "./deal";
import { dataField } from "../initial_identity/data-ports";
export const THIEF_POLICY = "lui_meme_thief_two_extra_villagers_v1" as const;
/** 只核原角色／三字段状态；成功保同一live引用，不新增camp、写权或不可反射对象要求。 */
export function getThiefState(role: RoleComponent | undefined): ThiefReadState | null {
  if (!role || dataField(role, "role") !== Role.Thief) return null;
  const state = dataField(dataField(role, "privateState"), "thief");
  if (!state || typeof state !== "object" || Array.isArray(state)) return null;
  const keys = Reflect.ownKeys(state);
  if (
    keys.length !== 3 ||
    !keys.every((key) => ["policy", "remaining", "choice"].includes(String(key)))
  )
    return null;
  // 原remaining和choice各自允许0／1，choice还允许null；这里只读字段，选择合法性由原scope继续核。
  const policy = dataField(state, "policy"),
    remaining = dataField(state, "remaining"),
    choice = dataField(state, "choice");
  return policy === THIEF_POLICY &&
    (remaining === 0 || remaining === 1) &&
    (choice === null || choice === 0 || choice === 1)
    ? (state as ThiefReadState)
    : null;
}
/** 新知识对象只调整显示remaining；原状态、policy和choice读取先后不变，副本不是可提交选择。 */
export function projectThiefState(
  role: RoleComponent | undefined,
  world: World,
): ThiefState | undefined {
  const s = getThiefState(role);
  if (!s) return;
  return {
    policy: s.policy,
    remaining: thiefSetupStatus(world) === "pending" ? s.remaining : 0,
    choice: s.choice,
  };
}
/** 只接受原唯一slot自有键及0／1值；descriptor字段读取不调用普通访问器，但反射仍可能失败。 */
export function readThiefChoice(value: unknown): 0 | 1 | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 1 || keys[0] !== "slot") return;
  const slot = dataField(value, "slot");
  return slot === 0 || slot === 1 ? slot : undefined;
}

/** 先核原两键与工具名，再读取args／slot；首个失败按原null结果或反射异常传播，不补新参数。 */
export function readThiefTool(
  value: unknown,
): import("../../../../core/domain").TypedToolCall<"choose_thief_card"> | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const keys = Reflect.ownKeys(value);
  if (
    keys.length !== 2 ||
    !keys.includes("name") ||
    !keys.includes("args") ||
    dataField(value, "name") !== "choose_thief_card"
  )
    return null;
  const slot = readThiefChoice(dataField(value, "args"));
  return slot === undefined ? null : { name: "choose_thief_card", args: { slot } };
}

/**
 * 负责 盗贼 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import { THIEF_POLICY, getThiefState, projectThiefState, readThiefChoice } from "./state";
import { authorizedThiefScope } from "./setup";
const parameters = z.strictObject({ policy: z.literal(THIEF_POLICY).default(THIEF_POLICY) });
export const THIEF_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Thief,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    label: roleName("thief"),
    skillBrief: text("zh-CN", "role.thief.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.Thief,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
    ],
  },
  runtime: {
    init: (role, ctx) => {
      if (!getThiefState(role))
        role.privateState.thief = {
          policy: ctx.boardConfig?.thief?.policy ?? THIEF_POLICY,
          remaining: 1,
          choice: null,
        };
    },
    configuration: {
      schema: parameters,
      defaults: { policy: THIEF_POLICY },
      apply: (config, value) => ({ ...config, thief: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.thief ?? {}),
    },
    toolSpecs: [
      {
        name: "choose_thief_card",
        parameters: {
          type: "object",
          properties: { slot: { type: "integer", enum: [0, 1] } },
          required: ["slot"],
          additionalProperties: false,
        },
        argHint: 'choose_thief_card args: {"slot":0|1}',
        userPromptHintKey: "action.choose_thief_card.hint",
      },
    ],
    validationRules: {
      choose_thief_card: ({ world, actorId, day, phase, toolCall, thiefScope }) => {
        if (!authorizedThiefScope(world, actorId, day, phase, thiefScope))
          return { code: RuleError.ThiefUnavailable };
        return toolCall.name === "choose_thief_card" && readThiefChoice(toolCall.args) !== undefined
          ? null
          : { code: RuleError.ThiefChoice };
      },
    },
    baselineAction: (_role, request) =>
      request.allowedTools.includes("choose_thief_card")
        ? { name: "choose_thief_card", args: { slot: 0 } }
        : null,
  },
  presentation: nativeRolePresentation("thief"),
};

/**
 * 提供盗贼玩家知识、原选择请求 scope 与选择字段 reader 的出口。展示只投影原获准
 * 可选牌，动作接收仍在原参数位置读同一 scope 与选择数据；读取不接受动作或授予
 * 新许可。原 setup 保持换牌、别名及关闭顺序，本出口不缓存当前性或渲染文案。
 */

export { projectThiefState } from "./state";

export { thiefRequestScope } from "./setup";

export { readThiefChoice } from "./state";

/**
 * 负责读取千面人私有状态结构并构造玩家投影，private 槽仍由原角色／初始化 owner 持有。
 * 输入为角色记录，投影另接收 World；输出为合法原槽引用或新 policy／remaining／choice
 * 视图。只在 setup 为 pending 时展示存储 remaining，其他 setup 状态投影为 0，不改 live 库存。
 * 具名工具出口引用同一 shared reader；本模块不发牌或提交身份替换，也不新增未知对象零 trap 保证。
 */
import type { ShapeshifterState, ShapeshifterReadState } from "@ai-werewolf-arena/game-contract";
import { Role, type RoleComponent, type World } from "../../../../core/domain";
import { shapeshifterSetupStatus } from "./deal";
export const SHAPESHIFTER_POLICY = "awa_netease_shapeshifter_two_extra_villagers_v1" as const;
import { dataField } from "../initial_identity/data-ports";
export function getShapeshifterState(
  role: RoleComponent | undefined,
): ShapeshifterReadState | null {
  if (!role || dataField(role, "role") !== Role.Shapeshifter) return null;
  const state = dataField(dataField(role, "privateState"), "shapeshifter");
  if (!state || typeof state !== "object" || Array.isArray(state)) return null;
  const keys = Reflect.ownKeys(state);
  if (
    keys.length !== 3 ||
    !keys.every((key) => ["policy", "remaining", "choice"].includes(String(key)))
  )
    return null;
  const policy = dataField(state, "policy"),
    remaining = dataField(state, "remaining"),
    choice = dataField(state, "choice");
  return policy === SHAPESHIFTER_POLICY &&
    (remaining === 0 || remaining === 1) &&
    (choice === null || choice === 0 || choice === 1)
    ? (state as ShapeshifterReadState)
    : null;
}
export function projectShapeshifterState(
  role: RoleComponent | undefined,
  world: World,
): ShapeshifterState | undefined {
  const s = getShapeshifterState(role);
  if (!s) return;
  return {
    policy: s.policy,
    remaining: shapeshifterSetupStatus(world) === "pending" ? s.remaining : 0,
    choice: s.choice,
  };
}
export function readShapeshifterChoice(value: unknown): 0 | 1 | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 1 || keys[0] !== "slot") return;
  const slot = dataField(value, "slot");
  return slot === 0 || slot === 1 ? slot : undefined;
}

export { readShapeshifterChoiceTool as readShapeshifterTool } from "@ai-werewolf-arena/game-contract/facts/shapeshifter";

/**
 * 负责 千面人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import {
  SHAPESHIFTER_POLICY,
  getShapeshifterState,
  projectShapeshifterState,
  readShapeshifterChoice,
} from "./state";
import { authorizedShapeshifterScope } from "./setup";
const parameters = z.strictObject({
  policy: z.literal(SHAPESHIFTER_POLICY).default(SHAPESHIFTER_POLICY),
});
export const SHAPESHIFTER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Shapeshifter,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    label: roleName("shapeshifter"),
    skillBrief: text("zh-CN", "role.shapeshifter.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.Shapeshifter,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
    ],
  },
  runtime: {
    init: (role, ctx) => {
      if (!getShapeshifterState(role))
        role.privateState.shapeshifter = {
          policy: ctx.boardConfig?.shapeshifter?.policy ?? SHAPESHIFTER_POLICY,
          remaining: 1,
          choice: null,
        };
    },
    configuration: {
      schema: parameters,
      defaults: { policy: SHAPESHIFTER_POLICY },
      apply: (config, value) => ({ ...config, shapeshifter: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.shapeshifter ?? {}),
    },
    toolSpecs: [
      {
        name: "choose_shapeshifter_card",
        parameters: {
          type: "object",
          properties: { slot: { type: "integer", enum: [0, 1] } },
          required: ["slot"],
          additionalProperties: false,
        },
        argHint: 'choose_shapeshifter_card args: {"slot":0|1}',
        userPromptHintKey: "action.choose_shapeshifter_card.hint",
      },
    ],
    validationRules: {
      choose_shapeshifter_card: ({ world, actorId, day, phase, toolCall, shapeshifterScope }) => {
        const scope = authorizedShapeshifterScope(world, actorId, day, phase, shapeshifterScope);
        if (!scope) return { code: RuleError.ShapeshifterUnavailable };
        return toolCall.name === "choose_shapeshifter_card" &&
          scope.allowedSlots.includes(readShapeshifterChoice(toolCall.args) as 0 | 1)
          ? null
          : { code: RuleError.ShapeshifterChoice };
      },
    },
    baselineAction: () => null,
  },
  presentation: nativeRolePresentation("shapeshifter"),
};

/**
 * 提供变形者已获玩家知识与原选择请求 scope 的出口。展示投影不暴露可选底牌之外的
 * 身份；动作接收在原参数位置读取同一 scope，不能从公布结果推断新许可。原 setup
 * 仍负责选择、换牌和关闭，本出口不缓存当前性、复制状态或执行文案格式化。
 * 查询时点由展示或接收调用方决定，出口不提前取得请求或捕获角色底牌。
 */

export { projectShapeshifterState } from "./state";

export { shapeshifterRequestScope } from "./setup";

/**
 * 负责构造野孩子数据、按 descriptor 读取 live 槽并解析原工具选择字段。
 * 状态由原角色及野孩子 lifecycle 所有者持有；输入为角色记录或工具候选，输出保留原槽
 * 引用及既有有限字段校验。此数据边界不改变阵营、提交生命或从副本取得转换权限。
 */
import type { WildChildState, WildChildReadState } from "@ai-werewolf-arena/game-contract";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
export const WILD_CHILD_POLICY = "awa_lui_meme_wild_child_v1" as const;
export function freshWildChildState(): WildChildState {
  return {
    policy: WILD_CHILD_POLICY,
    remaining: 1,
    status: "pending",
    choice: null,
    eligibleNight: null,
    activeFromNight: null,
  };
}
export function getWildChildState(role: RoleComponent | undefined): WildChildReadState | undefined {
  const container = role && Object.getOwnPropertyDescriptor(role, "privateState");
  const value =
    container &&
    Object.hasOwn(container, "value") &&
    container.value &&
    Object.getOwnPropertyDescriptor(container.value, "wildChild");
  return value && Object.hasOwn(value, "value") ? (value.value as WildChildReadState) : undefined;
}
export function readWildChildTool(
  value: unknown,
): { name: "choose_wild_model"; args: { target_id: number } } | null {
  try {
    const p = copyEventData(value) as Record<string, unknown> | null;
    const args = p?.args as Record<string, unknown> | undefined;
    return p &&
      Object.keys(p).length === 2 &&
      p.name === "choose_wild_model" &&
      args &&
      Object.keys(args).length === 1 &&
      Number.isSafeInteger(args.target_id) &&
      (args.target_id as number) > 0
      ? { name: "choose_wild_model", args: { target_id: args.target_id as number } }
      : null;
  } catch {
    return null;
  }
}

/**
 * 负责 野孩子 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import { WOLF_NIGHT_STAGES } from "../wolf/ability-ports";
import { WOLF_TOOL_SPECS, WOLF_STAGE_DIRECTIVES } from "../wolf/ability-ports";
import { WOLF_VALIDATION_RULES } from "../wolf/ability-ports";
import { WOLF_LLM_REPAIR_PACK } from "../wolf/ability-ports";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import {
  WILD_CHILD_POLICY,
  freshWildChildState,
  getWildChildState,
  readWildChildTool,
} from "./state";
import {
  authorizedWildChild,
  projectWildChild,
  wildChildPackActive,
  wildChildPackKnown,
} from "./lifecycle";
const parameters = z.strictObject({
  policy: z.literal(WILD_CHILD_POLICY).default(WILD_CHILD_POLICY),
});
export const WILD_CHILD_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.WildChild,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.WildChild,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
    ],
    label: roleName("wild_child"),
    skillBrief: text("zh-CN", "role.wild_child.brief"),
  },
  runtime: {
    canSelfDestruct: false,
    init: (role) => {
      if (!getWildChildState(role)) role.privateState.wildChild = freshWildChildState();
    },
    configuration: {
      schema: parameters,
      defaults: { policy: WILD_CHILD_POLICY },
      apply: (config, value) => ({ ...config, wildChild: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.wildChild ?? {}),
    },
    wolfTeam: (role, world) => ({
      recognizedByPack: wildChildPackKnown(role, world),
      recognizes: wildChildPackKnown(role, world) ? "pack" : "none",
      canChat: wildChildPackActive(role, world),
      canVoteForKill: wildChildPackActive(role, world),
    }),
    nightStages: WOLF_NIGHT_STAGES,
    stageDirectives: WOLF_STAGE_DIRECTIVES,
    toolSpecs: [
      ...WOLF_TOOL_SPECS.filter((spec) => spec.name !== "self_destruct"),
      {
        name: "choose_wild_model",
        parameters: {
          type: "object",
          properties: { target_id: { type: "integer" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'choose_wild_model args: {"target_id":number}',
        userPromptHintKey: "action.choose_wild_model.hint",
      },
    ],
    validationRules: {
      ...WOLF_VALIDATION_RULES,
      choose_wild_model: ({ world, actorId, day, phase, toolCall, wildChildScope }) =>
        !authorizedWildChild(world, actorId, day, phase, wildChildScope)
          ? { code: RuleError.WildChildUnavailable }
          : readWildChildTool(toolCall) &&
              toolCall.name === "choose_wild_model" &&
              toolCall.args.target_id !== actorId &&
              world.getAliveEntityIds().includes(toolCall.args.target_id)
            ? null
            : { code: RuleError.WildChildChoice },
    },
    llmRepair: WOLF_LLM_REPAIR_PACK,
    baselineAction: (role, request, pickAliveNotSelf, pickAliveByCamp, locale, world) =>
      request.allowedTools.includes("choose_wild_model")
        ? { name: "choose_wild_model", args: { target_id: pickAliveNotSelf()! } }
        : (ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pickAliveNotSelf,
            pickAliveByCamp,
            locale,
            world,
          ) ?? null),
  },
  presentation: nativeRolePresentation("wild_child"),
};

/**
 * 提供野孩子准备状态、夜间单元和原生命死亡标记的公开入口。输入保留原 World、日期和玩家序号；
 * 输出是原准备结果、关闭能力或绑定上的死亡标记。死亡标记在实际 Alive 修改之前写入，
 * 权限与失败、关闭状态由具体生命周期所有者校验。本入口不复制状态、不修改阵营，
 * 已提交整波的具体贡献仍按首次榜样死亡和原生命验证转换，在梦记录／遗言前运行；
 * 不是晚 deathHook 或新的死亡提交器，失败保留榜样事实及原已提交前缀。
 * 玩家知识及请求 scope／工具读取仍使用原函数绑定，不重新捕获榜样或生成死亡授权。
 */
export { hasActiveWildChild, wildChildReady, hasWildChildNightCommit, openWildChildNight } from "./lifecycle";

export { recordWildChildDeathCommit } from "./lifecycle";

/** 具名登记同一完整 owner 函数，不包装调用、不复制榜样绑定或重新判断生命。 */
export { resolveWildChildDeathWave } from "./lifecycle";

export { projectWildChild } from "./lifecycle";

export { wildChildRequestScope } from "./lifecycle";

export { readWildChildTool } from "./state";

/**
 * 负责构造孤独少女 policy／remaining／choice 数据并验证原角色状态槽。
 * 槽由原角色及关系 lifecycle 所有者持有，输入为角色记录，输出为复制校验通过后的原引用。
 * choice 的首夜字段与库存关系沿用原接受集合；查询不结算关系、公开底牌或提交库存。
 */
import type { LonelyGirlState, LonelyGirlReadState } from "@ai-werewolf-arena/game-contract";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { LONELY_GIRL_POLICY } from "@ai-werewolf-arena/game-contract/facts/lonely-girl";
import type { RoleComponent } from "../../../../core/domain";
export {
  LONELY_GIRL_POLICY,
  readLonelyGirlChoiceTool as readLonelyGirlTool,
