function fixture(roles = deck, extra: Partial<BoardConfig> = {}) {
  const config = { ...foxBoard(roles), ...extra };
  return { ...bootstrapGame(config, { fixedRoles: roles }), config, events: [] as GameEvent[] };
}

type Fixture = ReturnType<typeof fixture>;

const role = (g: Fixture, id = 1) => g.world.getComponent(id, COMPONENT.Role)!;

const victory = (g: Fixture) => g.world.getComponent(1, COMPONENT.Victory)!;

const choose = (target_id = 2): ToolCall => ({
  name: "choose_admired_player",
  args: { target_id },
});

const setup = (
  g: Fixture,
  body: (r: ActionRequest) => Promise<ToolCall | null> = async () => choose(),
  current = () => true,
  gateway = new ToolGateway(),
) =>
  new LonelyGirlSetupWindow(g.world, gateway, g.events, { get requestFactory() { return GameActionRequestFactory; } }).execute(
    g.config,
    { getAction: body },
    1,
    current,
  );

